"use client";

import * as SliderPrimitive from "@radix-ui/react-slider";

import { cn } from "@/lib/utils";

const Slider = ({
  className,
  defaultValue,
  value,
  min = 0,
  max = 100,
  onValueChange,
  ...props
}: React.ComponentProps<typeof SliderPrimitive.Root>) => {
  const thumbCount = (value ?? defaultValue ?? [0]).length;

  return (
    <SliderPrimitive.Root
      data-slot="slider"
      defaultValue={defaultValue}
      value={value}
      min={min}
      max={max}
      onValueChange={onValueChange}
      className={cn(
        "relative flex w-full touch-none items-center select-none",
        "data-[orientation=vertical]:h-full data-[orientation=vertical]:w-auto data-[orientation=vertical]:flex-col",
        "data-[disabled]:opacity-50",
        className,
      )}
      {...props}
    >
      <SliderPrimitive.Track
        data-slot="slider-track"
        className={cn(
          "bg-muted relative grow overflow-hidden rounded-full",
          "data-[orientation=horizontal]:h-1.5 data-[orientation=horizontal]:w-full",
          "data-[orientation=vertical]:h-full data-[orientation=vertical]:w-1.5",
        )}
      >
        <SliderPrimitive.Range
          data-slot="slider-range"
          className={cn(
            "bg-primary absolute",
            "data-[orientation=horizontal]:h-full",
            "data-[orientation=vertical]:w-full",
          )}
        />
      </SliderPrimitive.Track>
      {Array.from({ length: thumbCount }).map((_, i) => (
        <SliderPrimitive.Thumb
          key={i}
          data-slot="slider-thumb"
          className="border-primary bg-background ring-ring/50 block size-4 shrink-0 rounded-full border-2 shadow-sm transition-[color,box-shadow] outline-none focus-visible:ring-[3px] disabled:pointer-events-none"
        />
      ))}
    </SliderPrimitive.Root>
  );
};

export { Slider };
export default Slider;

"use client";

import { useState } from "react";

import { Slider } from "@/components/ui/slider";

export function SliderDemo() {
  const [single, setSingle] = useState([40]);
  const [range, setRange] = useState([20, 70]);
  const [stepped, setStepped] = useState([50]);

  return (
    <div className="flex flex-col gap-8 px-2">
      {/* Default */}
      <div className="flex flex-col gap-2">
        <div className="text-muted-foreground flex justify-between text-xs">
          <span>Volume</span>
          <span>{single[0]}%</span>
        </div>
        <Slider value={single} onValueChange={setSingle} min={0} max={100} sounds />
      </div>

      {/* Range */}
      <div className="flex flex-col gap-2">
        <div className="text-muted-foreground flex justify-between text-xs">
          <span>Price range</span>
          <span>
            ${range[0]} – ${range[1]}
          </span>
        </div>
        <Slider value={range} onValueChange={setRange} min={0} max={100} sounds />
      </div>

      {/* Stepped */}
      <div className="flex flex-col gap-2">
        <div className="text-muted-foreground flex justify-between text-xs">
          <span>Step (25)</span>
          <span>{stepped[0]}</span>
        </div>
        <Slider value={stepped} onValueChange={setStepped} min={0} max={100} step={25} sounds />
      </div>

      {/* Disabled */}
      <div className="flex flex-col gap-2">
        <span className="text-muted-foreground text-xs">Disabled</span>
        <Slider defaultValue={[60]} disabled />
      </div>

      {/* Vertical */}
      <div className="flex items-end gap-6">
        {[30, 60, 80].map((v, i) => (
          <Slider key={i} defaultValue={[v]} orientation="vertical" className="h-28" />
        ))}
      </div>
    </div>
  );
}


export default function Page() {
  return (
    <div className="flex min-h-svh items-center justify-center p-8 bg-background">
      <SliderDemo />
    </div>
  );
}
